package ro.leo.visual;
import android.content.*;import android.graphics.*;import android.os.Bundle;import android.view.*;import android.widget.*;import java.util.*;
public final class ThemePacksActivity extends LeoActivity {
 private int selected;
 protected void onCreate(Bundle b){super.onCreate(b);home();}
 private void home(){list("Colecții vizuale Leo",Arrays.asList(ThemePacks.NAMES),selected,new Choice(){public void pick(int n){preview(n);}},"",null);}
 private void preview(int n){selected=n;final Appearance.Palette sample=new Appearance.Palette(Appearance.COLORS[ThemePacks.THEMES[n]]);begin(ThemePacks.NAMES[n]);root.addView(new View(this){final Paint p=new Paint(3);void label(Canvas c,String s,int x,int y,int size,int color){p.setColor(color);p.setTextSize(size);c.drawText(s,x,y,p);}protected void onDraw(Canvas c){c.save();c.scale(getWidth()/240f,getHeight()/224f);c.drawColor(sample.background);p.setColor(sample.card);c.drawRoundRect(8,8,232,54,5,5,p);label(c,"LEO · Home",18,38,20,Color.WHITE);p.setColor(sample.selection);c.drawRoundRect(8,64,232,105,5,5,p);label(c,"Mesaje · Contacte",18,91,17,sample.ink);p.setColor(sample.card);c.drawRoundRect(8,116,232,157,5,5,p);label(c,"Muzică · Ceas",18,143,17,Color.WHITE);label(c,"Telefon + ecran de apel",12,181,15,sample.accent);label(c,"Aceleași culori în aplicațiile Leo",12,204,12,Color.WHITE);c.restore();}},new LinearLayout.LayoutParams(-1,0,1));left=new Runnable(){public void run(){options("Aplici colecția completă?",new String[]{"Păstrează stilul actual","Aplică peste temele pe aplicații"},new Choice(){public void pick(int yes){if(yes==1){try{ThemePacks.apply(ThemePacksActivity.this,selected);notice("Colecție aplicată · redeschide aplicațiile");home();}catch(RuntimeException e){notice("Aplicarea temei a eșuat");}}}});}};back=new Runnable(){public void run(){home();}};footer("Aplică","Mostră","Înapoi");}
}
